	 set nmsp = $get(%session.Data("Namespace"))
  	set env = $get(%session.Data("Environment"))
	set sql="select distinct c.ComponentName from IHC_ITF_SrcCtrlPkg.Component c"
	if (nmsp '= "")
 {
  set sql= sql _ ", IHC_ITF_SrcCtrlPkg.Namespaces n "
 }
 if (env '= "")
 {
  set sql= sql _ " , IHC_ITF_SrcCtrlPkg.ComponentImpl i,  IHC_ITF_SrcCtrlPkg.Environment e "
 }
 if (nmsp '= "")
 {
  set sql= sql _ " where c.NameSpace = n.ID AND n.NameSpace = '" _ nmsp _ "'"
 }
 if (env '= "")
 {
	 if (nmsp '= "")
 	{
	 	set sql= sql _ " AND "
 	}
 	else
 	{
	 	set sql= sql _ " where"
 	}
  set sql= sql _ " c.ID = i.ComponentName and i.Environment = e.ID AND e.Environment = '" _env _ "'"
 }
 set sql= sql _ " ORDER BY ComponentName"
  Set tRS = ##class(%ResultSet).%New()
    Set tSC = tRS.Prepare(sql)
    Set pInfo.queryText = sql

    Quit tRS


  set qt = $get(%session.Data("QueryType"))
  set compNm = $get(%session.Data("Component"))
  set nmsp = $get(%session.Data("Namespace"))
  set env = $get(%session.Data("Environment"))

  set sql=""
 if (qt = "C") // CLASS
 {
	 set sql= "select  c.ComponentName, ci.ClassName, ci.ClassExportFileVersion, i.ImplFileVersion as DeployVersion, i.ImplementionDate, "
	 _ " n.NameSpace, e.Environment, i.ImplFileInformation, ci.UserName "

 _ " from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.Namespaces n, "
 _ " IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e,"
 _ " IHC_ITF_SrcCtrlPkg.ClassItem ci "
 _ " where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID "
 _ " and i.ImplFile = ci.ClassExportFile and ci.importDate = i.ImplementionDate "
 }
 else // Implementation
 {
 set sql="select c.ComponentName, e.Environment, n.NameSpace, i.ImplFileVersion, i.ImplementionDate,"
 _ "  $EXTRACT(i.ImplFile, $FIND( i.ImplFile, 'trunk/'), 250) As DeployFileName , "
   _ "  i.ImplFileInformation, UserName"
  _ " from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.Namespaces n, "
  _ " IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e " 
  _ " where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID"
 }
  if (compNm '= "")
 {
  set sql= sql _ " AND c.ComponentName = '" _compNm _ "'"
 }
 if (nmsp '= "")
 {
  set sql= sql _ " AND n.NameSpace = '" _ nmsp _ "'"
 }
 if (env '= "")
 {
  set sql= sql _ " AND e.Environment = '" _env _ "'"
 }
 set sql= sql _ " ORDER BY i.ImplementionDate DESC"
  Set tRS = ##class(%ResultSet).%New()
    Set tSC = tRS.Prepare(sql)
    Set pInfo.queryText = sql

    Quit tRS

	set lstEnv = "" 
	  		 	set lstNmsp = ""
	  		 	set lstVer = ""
	  		 	set lstDt = ""

	set retStr = ""

		set implNum = 1
		set clsNum = 1

	if ( compNm '= "")
		{
			set retStr = retStr _  "<B>" _ compNm _ "</B><BR>"
	 		&sql(Declare Cl Cursor for select c.ComponentName, e.Environment, n.NameSpace, i.ImplFileVersion, i.ImplementionDate,
    			 ci.ClassExportFile, ci.ClassExportFileInformation, ci.ClassExportFileVersion, ci.ClassName, i.UserName
    			 INTO :cNm, :env, :nmsp, :implFlVer, :implDt, :clExpFl, :clsFlInfo, :clsVer, :clsNm, :usrNm
  				 from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.ClassItem ci, IHC_ITF_SrcCtrlPkg.Namespaces n,
  				 IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e  
 				  where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID
				 and i.ImplFile = ci.ClassExportFile and ci.importDate = i.ImplementionDate 
				 AND c.ComponentName = :compNm ORDER BY i.ImplementionDate desc)
   			Set SQLCODE=0  
			&sql(OPEN Cl) 

			WHILE(SQLCODE = 0)
			{
				 &sql(FETCH Cl)  
	  			 Quit:SQLCODE 
 			 	 IF SQLCODE = 0 
 				 { 
 					if ( (lstEnv '= env) || (lstNmsp '= nmsp) || (lstVer '= implFlVer) ||( lstDt '= implDt))
 					{
						set clsNum = 1
	  		 			set retStr = retStr _ "<p style=""font-size: 1em""> <BR>Deployment #" _ implNum _ ". Environment: " _ env _", Namespace: "_nmsp _", Deployment version # "_implFlVer _"<BR> Implemention Date: "_implDt _ " by "_usrNm _ "<BR><BR>"
	 					set implNum = implNum + 1

 					}
 					else
 					{
	 					set clsNum = clsNum + 1
 					}

	  		 		set retStr = retStr _  "<I> <p style=""font-size: smaller"">Class # " _ clsNum _ ". " _ "  Name: "_clsNm _ "<BR>  File: "
	  		 		_clExpFl _ "<BR>  Class Information: "_clsFlInfo_"<BR>  SubVersion # "_clsVer  _ "</I><BR><BR>"
	  		 		set lstEnv = env 
	  		 		set lstNmsp = nmsp
	  		 		set lstVer = implFlVer
	  		 		set lstDt = implDt
	 			}
	 			else
	 			{
		 			set retStr = retStr _ compNm _ ": " _ SQLCODE
	 			}
			}
			&sql(CLOSE Cl)
			if (retStr '= "")
			{
				 &sql(Declare C2 Cursor for select c.ComponentName, e.Environment, n.NameSpace, 
				 i.ImplFileVersion, i.ImplementionDate,
				 i.ImplFile As DeployFileName , 
    			i.ImplFileInformation, i.UserName
    			 INTO :cNm, :env, :nmsp, :implFlVer, :implDt, :deployFl, implFlInfo, :usrNm

 				 from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.Namespaces n,
   				IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e 
   				where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID
   				AND c.ComponentName = :compNm ORDER BY i.ImplementionDate desc)
   				Set SQLCODE=0  
				&sql(OPEN C2) 

				WHILE(SQLCODE = 0)
				{
				 &sql(FETCH C2)  
	  			 Quit:SQLCODE 

 			 	 IF SQLCODE = 0 
 				 { 
 				 		set retStr = retStr _ "<p style=""font-size: 1em""> <BR>Deployment #" _ implNum _ ". Environment: " _ env _", Namespace: "_nmsp _"<BR>Deployment file: " _ deployFl _ "<BR> Deployment version # "_implFlVer _"<BR> Implemention Date: "_implDt _ " by "_usrNm _ "<BR>" _ implFlInfo _ "<BR><BR>"
 				 }
 				 set implNum = implNum + 1
 				}
 				&sql(CLOSE C2)
			}
  		}


  return retStr

  try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
   set button = %page.%GetComponentById("changeFunc")
 	 if $ISOBJECT(button)
 	 {
	 	set button.caption = "ITF Common Deployment"
 	 }
 } catch err
 {
 }
 return $$$OK
